export const meta = {
  name: 'understand-shared-move',
  description: 'Map all layers needed to implement shared-folder move + the useFolderNavigation unwrap consolidation',
  phases: [{ title: 'Map' }],
}

phase('Map')

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'keySignatures', 'mechanics', 'filesAndLines', 'gotchas', 'openQuestions'],
  properties: {
    summary: { type: 'string', description: 'High-level summary of what this layer does relevant to the task' },
    keySignatures: {
      type: 'array',
      description: 'Exact function/method/type signatures relevant to implementing the feature, with file:line',
      items: { type: 'string' },
    },
    mechanics: {
      type: 'string',
      description: 'Step-by-step mechanics of the relevant flows (publish/sequence bookkeeping, re-encrypt steps, state updates). Be precise.',
    },
    filesAndLines: {
      type: 'array',
      description: 'Specific file:line references that an implementer must touch or mirror',
      items: { type: 'string' },
    },
    gotchas: {
      type: 'array',
      description: 'Crypto, sequence-number, state-desync, or other landmines',
      items: { type: 'string' },
    },
    openQuestions: {
      type: 'array',
      description: 'Things ambiguous or needing a design decision',
      items: { type: 'string' },
    },
  },
}

const READERS = [
  {
    key: 'private-move-reference',
    prompt: `Read-only investigation. In the cipher-box monorepo, study the PRIVATE-VAULT move + bin-restore reference implementation that todo #8 says shared-move must mirror.

Read these and trace them fully:
- packages/sdk/src/client.ts — find and fully read CipherBoxClient.moveItem and restoreFromBin (and any private helper they call for re-parenting / re-encryption).
- Any helper in packages/sdk/src that resolves a FileMetadata IPNS record, re-encrypts it with a destination folderKey, and re-publishes with createVersion:false.
- How folderTree state + IPNS sequenceNumber bookkeeping is advanced on a move/publish.

I need to understand EXACTLY how moveItem:
1. resolves the source file metadata,
2. re-encrypts the FileMetadata record from the source folderKey to the destination folderKey (AES-256-GCM),
3. republishes (createVersion:false) and updates the parent folder listings on both source and destination,
4. advances the IPNS sequence number / avoids stale-sequence 409s,
5. updates in-memory folderTree state.

Return exact signatures with file:line, the precise re-encrypt sequence, and any sequence/publish gotchas. This is the contract the shared version must replicate.`,
  },
  {
    key: 'shared-write-layer',
    prompt: `Read-only investigation in the cipher-box monorepo. Study the SHARED-FOLDER write layer so I can add a moveInSharedFolder operation.

Read fully:
- packages/sdk/src/share/shared-write.ts — every exported operation (uploadFile, createFolder, renameItem, deleteItem, updateSharedFile). For EACH, document its signature, how it resolves the target subfolder + its folderKey, how it encrypts/decrypts metadata, and how it publishes + advances the shared IPNS sequence number.
- The SDK client (packages/sdk/src/client.ts) methods that own sharedFolderTree state and call into shared-write.ts (e.g. the shared analogs of moveItem) — how sharedFolderTree differs from folderTree, how publishes/sequence bookkeeping work for shares, and how write-permission + signing keys flow through.
- Any types: how a shared subfolder carries its own folderKey, how the shared tree is structured, what a share's signing/ipns key handling looks like.

I specifically need: where does renameItem/deleteItem get the subfolder's folderKey from, and does any current shared op re-encrypt FileMetadata? Return exact signatures (file:line), the publish/sequence mechanics for shares, and every gotcha around sharedFolderTree state + signing keys + sequence numbers.`,
  },
  {
    key: 'web-ui-layer',
    prompt: `Read-only investigation in the cipher-box monorepo (apps/web). Study the web UI layer for shared folders AND the private-vault move UI, so I can add an onMove to the shared file browser.

Read fully:
- apps/web/src/hooks/useSharedWriteOps.ts — all exposed operations, their signatures, how they call the SDK client, how they handle loading/error/refresh state.
- apps/web/src/components/file-browser/SharedFileBrowser.tsx — how it renders ContextMenu, the isWritable gating, the existing onRename/onDelete wiring.
- The ContextMenu component it uses — its props (onRename/onDelete/onMove?), how items are passed.
- The PRIVATE-vault move UI for comparison: find where a private move is triggered from the UI (the non-shared FileBrowser + its hook, e.g. useFileOperations/useFolderMutations moveItem), including any move-target picker / folder-picker dialog component. Document how the destination folder is chosen in the UI.

Return: exact prop shapes and hook signatures (file:line), the existing rename/delete wiring pattern to mirror, the private move UI pattern (especially the destination folder picker), and any gotchas (folderTree-not-loaded, state refresh after mutation).`,
  },
  {
    key: 'todo7-unwrap-consolidation',
    prompt: `Read-only investigation in the cipher-box monorepo. This is for todo #7: consolidate the web useFolderNavigation key-unwrap into the SDK.

Read fully:
- apps/web/src/hooks/useFolderNavigation.ts — especially around line 242-249 where it ECIES-unwraps folderKeyEncrypted / ipnsPrivateKeyEncrypted. Document the WHOLE function/flow: what it unwraps, what it does with the unwrapped keys (the display/metadata-load path), what state it sets, and everything downstream that consumes those unwrapped values.
- packages/sdk/src/client.ts around line 484-491 — the SDK's own ECIES unwrap of the same fields, AND the ensureFolderLoaded method: its exact signature, what it returns, and the FolderState type it populates/returns.
- The FolderState type definition (find it) — what fields it exposes (folderKey, ipnsPrivateKey, listings, etc.).

I need to know: can useFolderNavigation call client.ensureFolderLoaded(ipnsName) and read back a FolderState that already contains everything the web-side unwrap currently computes? Map field-by-field what the web unwrap produces vs what ensureFolderLoaded's FolderState exposes. Flag ANY value the web path needs that the SDK FolderState does NOT currently expose (that would require an SDK change). Also describe the MEDIUM security note: ensureFolderLoaded re-walking the whole reachable tree on a cache miss for an unreachable target with no negative cache.

Return exact signatures (file:line), the field-by-field mapping, and what (if anything) blocks a clean swap.`,
  },
  {
    key: 'e2e-test-reference',
    prompt: `Read-only investigation in the cipher-box monorepo. Study the e2e test setup so I can write a "decrypted content survives a within-share move" test.

Read fully:
- tests/web-e2e/tests/move-restore-content.spec.ts — the full test: how it sets up a vault, uploads a file with known content, moves it, and asserts the content still decrypts/downloads correctly. Document the fixtures/helpers it uses.
- The shared-folder e2e tests (find them under tests/web-e2e/tests/ — anything with "share" in the name): how a share is created, how a second client/recipient with write permission is set up, how cross-client sync is awaited.
- Any shared test helpers/fixtures (page objects, login helpers, the dev-stack setup) these rely on.

Return: the exact structure of move-restore-content.spec.ts (file:line of key steps), the shared-folder test setup pattern (two-client + write permission + sync wait), the helpers available, and a concrete outline of how the new within-share-move-preserves-content e2e should be assembled. Note any infra gotchas (does web-e2e only run on main push? local stack requirements?).`,
  },
]

const results = await parallel(
  READERS.map((r) => () =>
    agent(r.prompt, { label: r.key, phase: 'Map', schema: SCHEMA }).then((res) => ({ key: r.key, res }))
  )
)

return results.filter(Boolean)

